import balconyMoon from './balcony-moon.webm?url';
import mountainStars from './mountain-stars.png?url';
import nightTrain from './night-train.jpg?url';
import rainStreet from './rain-street.webp?url';
import roomTone from './room-tone.mp3?url';
import seaSunset from './sea-sunset.jpg?url';
import { loadDemoAssets } from '@/data/local/seed';

/** Fictional demo media generated by scripts/generate-demo-media.mjs. */
export const DEMO_ASSET_URLS: Record<string, string> = {
  'sea-sunset.jpg': seaSunset,
  'rain-street.webp': rainStreet,
  'mountain-stars.png': mountainStars,
  'night-train.jpg': nightTrain,
  'room-tone.mp3': roomTone,
  'balcony-moon.webm': balconyMoon,
};

export function loadDemoAssetsFromBundle(): Promise<Map<string, Blob>> {
  return loadDemoAssets((key) => DEMO_ASSET_URLS[key]);
}
